INSERT INTO `Knowledge_articles` VALUES (1,'Cách đặt lại mật khẩu tài khoản nội bộ','dat-lai-mat-khau-tai-khoan','Các bước xử lý khi quên mật khẩu hoặc tài khoản bị khóa.','Truy cập trang đăng nhập và chọn yêu cầu hỗ trợ tài khoản. Xác nhận email công ty, mã nhân viên và phòng ban. Bộ phận IT sẽ xác minh danh tính trước khi cấp mật khẩu tạm thời. Sau khi đăng nhập, hãy đổi mật khẩu mới và không sử dụng lại mật khẩu gần nhất.','account,password,security',1,15,5,'2026-05-01 18:19:29.434','2026-07-30 18:20:38.800'),(2,'Xử lý khi không kết nối được Wi-Fi văn phòng','xu-ly-khi-khong-ket-noi-duoc-wifi','Kiểm tra nhanh kết nối mạng trước khi gửi ticket.','Tắt và bật lại Wi-Fi, sau đó chọn đúng mạng OfficeFlow-Staff. Kiểm tra chế độ máy bay và thử quên mạng rồi kết nối lại bằng tài khoản công ty. Nếu nhiều thiết bị cùng mất mạng, hãy ghi rõ khu vực, tầng và thời điểm xảy ra để IT kiểm tra access point.','network,wifi,connectivity',1,22,6,'2026-05-06 18:19:29.434','2026-07-30 18:20:39.776'),(3,'Cấu hình VPN khi làm việc từ xa','cau-hinh-vpn-lam-viec-tu-xa','Hướng dẫn kết nối an toàn vào hệ thống nội bộ.','Cài ứng dụng VPN theo gói cài đặt do IT cung cấp. Đăng nhập bằng email công ty và mã xác thực đa yếu tố. Chỉ kết nối VPN khi cần truy cập tài nguyên nội bộ. Nếu xuất hiện lỗi chứng chỉ, không bỏ qua cảnh báo mà hãy chụp màn hình và gửi ticket cho IT.','vpn,network,remote-work,security',1,29,7,'2026-05-11 18:19:29.434','2026-07-30 18:20:40.750'),(4,'Khắc phục Outlook không đồng bộ email','khac-phuc-outlook-khong-dong-bo-email','Các bước xử lý khi thư đến không cập nhật hoặc gửi thư thất bại.','Kiểm tra trạng thái mạng và dung lượng hộp thư trước. Đóng Outlook hoàn toàn rồi mở lại, sau đó kiểm tra chế độ Work Offline. Nếu lỗi vẫn còn, ghi lại mã lỗi, thời điểm gửi nhận gần nhất và tên hộp thư bị ảnh hưởng để bộ phận IT kiểm tra cấu hình.','email,outlook,sync',1,36,8,'2026-05-16 18:19:29.434','2026-07-30 18:20:41.748'),(5,'Xử lý máy in không nhận lệnh','xu-ly-may-in-khong-nhan-lenh','Kiểm tra hàng đợi in, kết nối và trạng thái thiết bị.','Xác nhận máy in đang bật, có giấy và không báo kẹt giấy. Mở hàng đợi in để xóa các lệnh bị treo, sau đó in lại một trang thử. Không tự tháo linh kiện bên trong máy. Khi gửi ticket, hãy cung cấp mã tài sản của máy in và thông báo lỗi trên màn hình.','printer,hardware,office',1,44,6,'2026-05-21 18:19:29.434','2026-07-30 18:30:34.796'),(6,'Yêu cầu cấp quyền thư mục dùng chung','yeu-cau-cap-quyen-thu-muc-dung-chung','Thông tin cần có để yêu cầu quyền truy cập dữ liệu phòng ban.','Ticket cần ghi rõ đường dẫn thư mục, loại quyền cần cấp và thời hạn sử dụng. Người yêu cầu phải có xác nhận của quản lý trực tiếp hoặc chủ sở hữu dữ liệu. IT chỉ cấp đúng phạm vi đã được phê duyệt và sẽ thu hồi quyền khi hết thời hạn.','access,permission,shared-folder',1,50,2,'2026-05-26 18:19:29.434','2026-07-30 18:20:43.694'),(7,'Cách báo cáo email nghi ngờ lừa đảo','bao-cao-email-nghi-ngo-lua-dao','Xử lý an toàn khi nhận email có liên kết hoặc tệp đáng ngờ.','Không nhấp vào liên kết, không mở tệp đính kèm và không trả lời người gửi. Sử dụng chức năng báo cáo phishing trong Outlook, sau đó tạo ticket Security kèm tiêu đề email và thời điểm nhận. Nếu đã nhập mật khẩu vào trang lạ, hãy liên hệ IT ngay để khóa phiên đăng nhập.','security,email,phishing',1,57,7,'2026-05-31 18:19:29.434','2026-07-30 18:20:44.612'),(8,'Kiểm tra bảo hành thiết bị được cấp','kiem-tra-bao-hanh-thiet-bi','Cách xem thông tin bảo hành và báo lỗi tài sản.','Mở trang Quản lý tài sản và chọn thiết bị đang được cấp cho bạn. Kiểm tra mã tài sản, số serial và ngày hết hạn bảo hành. Khi thiết bị gặp lỗi, hãy tạo ticket và liên kết đúng tài sản để IT có đủ thông tin làm việc với nhà cung cấp.','asset,warranty,hardware',1,64,5,'2026-06-05 18:19:29.434','2026-07-30 18:20:45.498'),(9,'Cập nhật ứng dụng nội bộ an toàn','cap-nhat-ung-dung-noi-bo','Các lưu ý trước khi nâng cấp phần mềm trên máy công ty.','Lưu công việc đang mở và kết nối nguồn điện trước khi cập nhật. Chỉ cài đặt bản cập nhật từ Software Center hoặc nguồn do IT công bố. Không tải bộ cài từ trang không xác định. Nếu cập nhật thất bại, hãy chụp mã lỗi và không gỡ ứng dụng thủ công.','software,update,security',1,71,8,'2026-06-10 18:19:29.434','2026-07-30 18:20:46.495'),(10,'Quy trình bàn giao và thu hồi tài sản','quy-trinh-ban-giao-thu-hoi-tai-san','Các bước cần thực hiện khi nhận hoặc trả thiết bị công ty.','Khi nhận thiết bị, kiểm tra mã tài sản, phụ kiện và tình trạng thực tế. Không chuyển thiết bị cho người khác nếu chưa có xác nhận trên hệ thống. Khi thu hồi, sao lưu dữ liệu công việc, đăng xuất tài khoản cá nhân và bàn giao đầy đủ phụ kiện cho IT.','asset,assignment,return',1,78,2,'2026-06-15 18:19:29.434','2026-07-30 18:20:47.502'),(11,'Hướng dẫn cài đặt máy in trên macOS','huong-dan-cai-dat-may-in-mac','Bản nháp hướng dẫn thêm máy in mạng cho MacBook.','Mở System Settings, chọn Printers and Scanners và thêm máy in theo địa chỉ IP nội bộ. Chọn đúng driver theo model thiết bị và in trang kiểm tra. Nội dung này đang được IT xác minh thêm danh sách driver tương thích trước khi xuất bản.','printer,macos,draft',0,1,6,'2026-06-20 18:19:29.434','2026-07-30 18:29:58.668'),(12,'Chính sách sử dụng thiết bị cá nhân','chinh-sach-thiet-bi-ca-nhan','Bản nháp về điều kiện kết nối thiết bị cá nhân vào mạng công ty.','Thiết bị cá nhân phải được cập nhật hệ điều hành, bật khóa màn hình và không lưu dữ liệu nhạy cảm của công ty. Quy trình đăng ký và phạm vi mạng được phép truy cập đang chờ bộ phận An toàn thông tin phê duyệt chính thức.','security,byod,draft',0,1,7,'2026-06-25 18:19:29.434','2026-07-30 18:30:17.583');
/*!40000 ALTER TABLE `Knowledge_articles` ENABLE KEYS */;
