--
-- Table structure for table `Tickets`
--

DROP TABLE IF EXISTS `Tickets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Tickets` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('OPEN','IN_PROGRESS','RESOLVED','CLOSED','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN',
  `priority` enum('LOW','MEDIUM','HIGH','URGENT') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM',
  `dueAt` datetime(3) DEFAULT NULL,
  `resolveAt` datetime(3) DEFAULT NULL,
  `isOverdue` tinyint(1) NOT NULL DEFAULT '0',
  `createdById` int NOT NULL,
  `assignedToId` int DEFAULT NULL,
  `categoryId` int DEFAULT NULL,
  `assetId` int DEFAULT NULL,
  `dueDate` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `Tickets_status_idx` (`status`),
  KEY `Tickets_priority_idx` (`priority`),
  KEY `Tickets_createdAt_idx` (`createdAt`),
  KEY `Tickets_assignedToId_idx` (`assignedToId`),
  KEY `Tickets_createdById_idx` (`createdById`),
  KEY `Tickets_categoryId_idx` (`categoryId`),
  KEY `Tickets_assetId_idx` (`assetId`),
  CONSTRAINT `Tickets_assetId_fkey` FOREIGN KEY (`assetId`) REFERENCES `Assets` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Tickets_assignedToId_fkey` FOREIGN KEY (`assignedToId`) REFERENCES `Users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Tickets_categoryId_fkey` FOREIGN KEY (`categoryId`) REFERENCES `Ticket_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Tickets_createdById_fkey` FOREIGN KEY (`createdById`) REFERENCES `Users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1038 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `Tickets`
--

LOCK TABLES `Tickets` WRITE;
/*!40000 ALTER TABLE `Tickets` DISABLE KEYS */;
INSERT INTO `Tickets` VALUES (1001,'Laptop không khởi động sau khi cập nhật','Máy Dell Latitude hiển thị màn hình đen sau bản cập nhật tối qua, đèn nguồn vẫn sáng nhưng không vào được Windows.','IN_PROGRESS','HIGH','2026-07-30 10:19:29.434',NULL,1,9,6,1,1,'2026-07-30 10:19:29.434','2026-07-29 10:19:29.434','2026-08-04 17:55:57.863'),(1002,'Pin laptop tụt nhanh khi họp trực tuyến','Pin giảm từ 100% xuống còn 30% sau khoảng một giờ họp Teams dù máy mới được sạc đầy vào đầu buổi.','IN_PROGRESS','MEDIUM','2026-08-02 10:19:29.434',NULL,1,10,6,1,NULL,'2026-08-02 10:19:29.434','2026-07-30 10:19:29.434','2026-08-04 17:00:01.906'),(1003,'Màn hình ngoài bị nhấp nháy','Màn hình Dell P2422H nhấp nháy liên tục khi kết nối qua dock USB-C, đổi cáp HDMI vẫn còn lỗi.','RESOLVED','MEDIUM','2026-07-27 14:19:29.434','2026-07-27 10:19:29.434',0,11,7,1,12,'2026-07-27 14:19:29.434','2026-07-24 14:19:29.434','2026-07-30 18:20:52.390'),(1004,'Bàn phím laptop không nhận phím Enter','Phím Enter và Backspace không phản hồi, bàn phím rời vẫn hoạt động bình thường trên cùng thiết bị.','CLOSED','LOW','2026-07-27 12:19:29.434','2026-07-27 08:19:29.434',0,12,8,1,NULL,'2026-07-27 12:19:29.434','2026-07-20 12:19:29.434','2026-07-30 18:20:53.355'),(1005,'Excel đóng đột ngột khi mở báo cáo','Excel tự thoát khi mở báo cáo doanh thu tháng có nhiều PivotTable, các tệp nhỏ vẫn mở bình thường.','IN_PROGRESS','HIGH','2026-07-31 10:19:29.434',NULL,1,13,8,2,NULL,'2026-07-31 10:19:29.434','2026-07-30 10:19:29.434','2026-08-04 17:55:26.980'),(1006,'Không cài được bản cập nhật phần mềm kế toán','Trình cài đặt báo thiếu quyền quản trị ở bước cập nhật cơ sở dữ liệu, cần IT hỗ trợ ngoài giờ chốt sổ.','CANCELLED','URGENT','2026-07-27 08:19:29.434',NULL,0,14,NULL,2,NULL,'2026-07-27 08:19:29.434','2026-07-27 04:19:29.434','2026-07-30 18:20:55.189'),(1007,'Teams không nhận micro tai nghe','Tai nghe Logitech được Windows nhận nhưng Teams không hiển thị trong danh sách thiết bị âm thanh.','OPEN','MEDIUM','2026-07-30 04:19:29.434',NULL,1,15,7,2,NULL,'2026-07-30 04:19:29.434','2026-07-27 04:19:29.434','2026-07-30 18:20:56.174'),(1008,'Trình duyệt tự chuyển sang trang quảng cáo','Chrome xuất hiện tab quảng cáo sau khi mở một số trang nội bộ, nghi ngờ có extension không an toàn.','IN_PROGRESS','HIGH','2026-07-31 10:19:29.434',NULL,1,16,8,2,NULL,'2026-07-31 10:19:29.434','2026-07-30 10:19:29.434','2026-08-04 17:00:01.906'),(1009,'Wi-Fi tầng 3 kết nối chập chờn','Nhiều nhân viên khu vực phòng họp tầng 3 bị rớt Wi-Fi khoảng mỗi 10 phút trong buổi sáng.','CLOSED','HIGH','2026-07-27 02:19:29.434','2026-08-04 17:51:36.675',0,9,7,3,22,'2026-07-27 02:19:29.434','2026-07-26 02:19:29.434','2026-08-04 17:51:37.153'),(1010,'Không truy cập được thư mục mạng Finance','Máy vẫn truy cập Internet nhưng đường dẫn thư mục dùng chung của Finance báo Network path not found.','CLOSED','HIGH','2026-07-27 00:19:29.434','2026-07-26 20:19:29.434',0,10,6,3,NULL,'2026-07-27 00:19:29.434','2026-07-26 00:19:29.434','2026-07-30 18:20:59.163'),(1011,'VPN ngắt kết nối sau vài phút','VPN kết nối thành công từ mạng gia đình nhưng tự ngắt sau ba đến năm phút, đã thử khởi động lại router.','RESOLVED','MEDIUM','2026-08-02 10:19:29.434','2026-08-13 18:58:13.452',1,11,6,3,22,'2026-08-02 10:19:29.434','2026-07-30 10:19:29.434','2026-08-13 18:58:13.452'),(1012,'Phòng họp mới chưa có cổng mạng hoạt động','Hai ổ cắm mạng tại phòng họp Operations chưa cấp được địa chỉ IP cho laptop và thiết bị hội nghị.','CANCELLED','LOW','2026-07-26 20:19:29.434',NULL,0,12,NULL,3,NULL,'2026-07-26 20:19:29.434','2026-07-19 20:19:29.434','2026-07-30 18:21:01.146'),(1013,'Outlook không nhận thư mới','Outlook hiển thị trạng thái Connected nhưng thư đến không cập nhật từ 9 giờ sáng, webmail vẫn có thư.','OPEN','HIGH','2026-07-30 06:19:29.434',NULL,1,13,NULL,4,NULL,'2026-07-30 06:19:29.434','2026-07-29 06:19:29.434','2026-07-30 18:21:02.118'),(1014,'Email gửi khách hàng bị trả lại','Các email gửi tới tên miền đối tác đều bị trả lại với mã lỗi 550, gửi nội bộ vẫn thành công.','CLOSED','URGENT','2026-07-30 20:59:29.434','2026-07-30 18:35:37.371',0,14,6,4,NULL,'2026-07-30 20:59:29.434','2026-07-30 16:59:29.434','2026-07-30 18:35:37.854'),(1015,'Chữ ký email hiển thị sai logo','Logo trong chữ ký Outlook bị vỡ tỷ lệ và không hiển thị khi người nhận mở thư trên điện thoại.','RESOLVED','LOW','2026-07-26 14:19:29.434','2026-07-26 10:19:29.434',0,15,7,4,NULL,'2026-07-26 14:19:29.434','2026-07-19 14:19:29.434','2026-07-30 18:21:04.009'),(1016,'Hộp thư phòng ban gần đầy dung lượng','Shared mailbox của Marketing đã dùng hơn 95% dung lượng và bắt đầu không nhận được tệp đính kèm lớn.','CLOSED','MEDIUM','2026-07-26 12:19:29.434','2026-07-26 20:19:29.434',1,16,8,4,NULL,'2026-07-26 12:19:29.434','2026-07-23 12:19:29.434','2026-07-30 18:21:04.914'),(1017,'Tài khoản bị khóa sau nhiều lần đăng nhập','Người dùng không thể đăng nhập máy tính và Outlook sau khi nhập sai mật khẩu nhiều lần vào sáng nay.','IN_PROGRESS','HIGH','2026-07-31 10:19:29.434',NULL,1,9,6,5,NULL,'2026-07-31 10:19:29.434','2026-07-30 10:19:29.434','2026-08-04 17:52:58.960'),(1018,'Không nhận được mã xác thực đa yếu tố','Ứng dụng Authenticator không hiển thị yêu cầu xác nhận khi đăng nhập VPN từ thiết bị công ty.','CANCELLED','URGENT','2026-07-26 08:19:29.434',NULL,0,10,NULL,5,NULL,'2026-07-26 08:19:29.434','2026-07-26 04:19:29.434','2026-07-30 18:21:06.921'),(1019,'Cập nhật số điện thoại khôi phục tài khoản','Nhân viên đã đổi số điện thoại công việc và cần cập nhật thông tin xác thực cho tài khoản Microsoft 365.','OPEN','LOW','2026-07-30 08:19:29.434',NULL,1,11,7,5,NULL,'2026-07-30 08:19:29.434','2026-07-23 08:19:29.434','2026-07-30 18:21:07.913'),(1020,'Tên hiển thị trên Teams chưa đúng','Tên hiển thị vẫn dùng thông tin cũ sau khi phòng HR đã cập nhật hồ sơ nhân sự từ tuần trước.','IN_PROGRESS','LOW','2026-08-06 10:19:29.434',NULL,1,12,8,5,NULL,'2026-08-06 10:19:29.434','2026-07-30 10:19:29.434','2026-08-06 16:00:01.213'),(1021,'Máy in Finance bị kẹt giấy liên tục','Máy in HP LaserJet báo kẹt giấy ở khay số 2 dù đã lấy hết giấy và vệ sinh con lăn.','RESOLVED','HIGH','2026-07-26 02:19:29.434','2026-07-26 10:19:29.434',1,13,NULL,6,17,'2026-07-26 02:19:29.434','2026-07-25 02:19:29.434','2026-07-30 18:21:09.878'),(1022,'Không tìm thấy máy in màu Marketing','Máy in mạng không còn xuất hiện sau khi laptop được cài lại Windows, cần thêm lại đúng driver.','CLOSED','MEDIUM','2026-07-26 00:19:29.434','2026-07-25 20:19:29.434',0,14,6,6,NULL,'2026-07-26 00:19:29.434','2026-07-23 00:19:29.434','2026-07-30 18:21:10.871'),(1023,'Bản in bị sọc đen dọc trang','Tất cả tài liệu in từ Canon imageRUNNER đều có một sọc đen ở mép phải, bản scan không bị ảnh hưởng.','OPEN','MEDIUM','2026-08-02 10:19:29.434',NULL,1,15,7,6,17,'2026-08-02 10:19:29.434','2026-07-30 10:19:29.434','2026-08-04 17:00:01.906'),(1024,'Yêu cầu cài máy in cho nhân viên mới','Nhân viên mới phòng HR cần được cài máy in gần khu vực làm việc và cấu hình in hai mặt mặc định.','CANCELLED','LOW','2026-07-25 20:19:29.434',NULL,0,16,NULL,6,NULL,'2026-07-25 20:19:29.434','2026-07-18 20:19:29.434','2026-07-30 18:21:12.797'),(1025,'Cấp quyền thư mục báo cáo quý','Cần quyền đọc và chỉnh sửa thư mục báo cáo quý của Finance trong thời gian chuẩn bị kiểm toán nội bộ.','CLOSED','HIGH','2026-07-30 10:19:29.434','2026-08-04 18:34:29.805',1,9,6,7,NULL,'2026-07-30 10:19:29.434','2026-07-29 10:19:29.434','2026-08-04 18:34:30.270'),(1026,'Cấp quyền truy cập phần mềm CRM','Nhân viên Marketing mới cần tài khoản CRM với phạm vi khách hàng khu vực miền Nam theo phê duyệt quản lý.','IN_PROGRESS','MEDIUM','2026-08-02 10:19:29.434',NULL,1,10,6,7,NULL,'2026-08-02 10:19:29.434','2026-07-30 10:19:29.434','2026-08-04 17:00:01.906'),(1027,'Thu hồi quyền của nhân viên nghỉ việc','Cần khóa tài khoản và thu hồi quyền truy cập các thư mục dùng chung trước 17 giờ theo yêu cầu của HR.','RESOLVED','URGENT','2026-07-25 14:19:29.434','2026-07-25 10:19:29.434',0,11,7,7,NULL,'2026-07-25 14:19:29.434','2026-07-25 10:19:29.434','2026-07-30 18:21:15.625'),(1028,'Mở quyền xem dashboard vận hành','Quản lý Operations cần quyền chỉ xem dashboard hiệu suất, không yêu cầu quyền chỉnh sửa cấu hình.','CLOSED','LOW','2026-07-25 12:19:29.434','2026-07-25 08:19:29.434',0,12,8,7,NULL,'2026-07-25 12:19:29.434','2026-07-18 12:19:29.434','2026-07-30 18:21:16.631'),(1029,'Phát hiện email yêu cầu thanh toán bất thường','Email giả mạo giám đốc yêu cầu chuyển khoản khẩn, người nhận chưa nhấp liên kết và đã chuyển tiếp cho IT.','CLOSED','URGENT','2026-07-30 20:59:29.434','2026-07-30 18:35:09.981',0,13,7,8,19,'2026-07-30 20:59:29.434','2026-07-30 16:59:29.434','2026-07-30 18:35:10.451'),(1030,'Máy tính cảnh báo phần mềm độc hại','Windows Security phát hiện tệp đáng ngờ trong thư mục Downloads và đang yêu cầu khởi động lại để xử lý.','CANCELLED','URGENT','2026-07-25 08:19:29.434',NULL,0,14,NULL,8,NULL,'2026-07-25 08:19:29.434','2026-07-25 04:19:29.434','2026-07-30 18:21:18.597'),(1031,'Thất lạc điện thoại công ty','Điện thoại được cấp cho quản lý có thể đã thất lạc khi di chuyển, cần khóa thiết bị và tài khoản từ xa.','OPEN','URGENT','2026-07-30 04:19:29.434',NULL,1,15,7,8,19,'2026-07-30 04:19:29.434','2026-07-30 00:19:29.434','2026-07-30 18:21:19.582'),(1032,'Kiểm tra đăng nhập từ vị trí lạ','Người dùng nhận thông báo đăng nhập từ quốc gia khác nhưng xác nhận không thực hiện hoạt động này.','IN_PROGRESS','HIGH','2026-07-31 10:19:29.434',NULL,1,16,8,8,NULL,'2026-07-31 10:19:29.434','2026-07-30 10:19:29.434','2026-08-04 17:00:01.906'),(1033,'Chuẩn bị thiết bị cho nhân viên mới','Cần chuẩn bị laptop, màn hình và tài khoản cơ bản cho nhân viên Operations bắt đầu làm việc vào thứ Hai.','CLOSED','MEDIUM','2026-07-25 02:19:29.434','2026-08-04 18:35:12.212',0,9,5,9,14,'2026-07-25 02:19:29.434','2026-07-22 02:19:29.434','2026-08-04 18:35:12.680'),(1034,'Di chuyển thiết bị sang khu vực làm việc mới','Bộ phận Marketing chuyển chỗ ngồi và cần IT hỗ trợ đấu nối lại màn hình, dock và cáp mạng.','CLOSED','LOW','2026-07-